let data = $input.first().json.data;
let body = $input.first().json.body;

//let prompt = JSON.stringify("Summarize the meeting notes. Respond with JSON format { summary: 'ai summary' }: " + JSON.stringify(data));

return [{
  data: data,
  file_type: body.file_type,
