}];

let body = $input.first().json.body;
let data = $input.first().json.data;
let prompt = "Summarize the document... raw content: " + data;

return [{
  json: {
    prompt: prompt,
    model: "global.anthropic.claude-haiku-4-5-20251001-v1:0",
    node_name: "DSE_ProjectDoc",
    workflow_id: "document-summary-extractor",
    workflow_session_id: "dse_" + body.project_id + "_" + Date.now(),
    memory_id: "memory_gp8vo-N6dx8qAYMs",
    client_id: "client_" + body.client_id,
    project_id: "project_" + body.project_id
  }
}];

let body = $input.first().json.body;
let prompt = "Project Info Updated: " + JSON.stringify(body.data);
return [{
  json: {
    prompt: prompt,
    model: "global.anthropic.claude-haiku-4-5-20251001-v1:0",
    node_name: "DSE_ProjectInfo",
    workflow_id: "document-summary-extractor",
    workflow_session_id: "dse_" + body.project_id + "_" + Date.now(),
    memory_id: "memory_gp8vo-N6dx8qAYMs",
    client_id: "client_" + body.client_id,
    project_id: "project_" + body.project_id
  }
}];

// Handle LLM sub-workflow error
const errorMsg = $input.first().json.error?.message || $input.first().json.message || 'LLM processing failed';
return [{
  json: {
    error_message: errorMsg,
    meeting_note_id: $('Meeting Notes Prompt Generator1').first().json.meeting_note_id
  }
}];

let body = $('Meeting Notes Prompt Generator').first().json;
let promptTemplate = $input.first().json.prompt;
let prompt = promptTemplate.replace("$raw_file_content", JSON.stringify(body.data));

return [{
  json: {
    prompt: prompt,
    model: "global.anthropic.claude-haiku-4-5-20251001-v1:0",
    node_name: "DSE_MeetingNotes",
    workflow_id: "document-summary-extractor",
    workflow_session_id: "dse_" + body.project_id + "_" + Date.now(),
    client_id: "client_" + body.client_id,
    project_id: "project_" + body.project_id,
    meeting_note_id: body.meeting_note_id
  }
}];

// Parse LLM sub-workflow response (already parsed JSON)
const llmResponse = $input.first().json.llm_response;

return [{
  json: {
    document_summary: llmResponse.document_summary,
    ai_observations: llmResponse.ai_observations,
    meeting_note_id: $('Meeting Notes Prompt Generator1').first().json.meeting_note_id
  }
}];

// Format input for drive-utils sub-workflow
const body = $('Webhook').first().json.body;
return [{
  json: {
    mode: "EXTRACT_CONTENT",
    google_drive_file_url: body.google_drive_url
  }
}];

// Bridge drive-utils output to downstream nodes
// On success: merge webhook body with extracted text
// On error: flag extraction_error
try {
  const result = $input.first().json;
  // Check for sub-workflow error indicators
  if (result.error || result.validation_errors?.length > 0 || result.status === 'error') {
    return [{ json: { extraction_error: true, error_message: result.error || result.validation_errors?.[0]?.message || 'Drive extraction failed' } }];
  }
  const body = $('Webhook').first().json.body;
  const extractedText = result.extracted_text || result.data?.extracted_text || '';
  if (!extractedText) {
    return [{ json: { extraction_error: true, error_message: 'No text extracted from document' } }];
  }
  return [{ json: { body: body, data: extractedText } }];
} catch (e) {
  return [{ json: { extraction_error: true, error_message: 'Drive extraction error: ' + e.message } }];
}

// Format error for coreapi — report extraction failure
const body = $('Webhook').first().json.body;
return [{
  json: {
    meeting_note_id: body.meeting_note_id,
    error_message: $json.error_message || 'Could not extract content from Google Drive document'
  }
}];

